package org.deeptimeline.app
import java.io.ByteArrayOutputStream
import java.io.DataOutputStream
import java.io.File
object RasterTests{fun check(){val names=listOf("America/Denver","Asia/Tokyo");val palette=ByteArrayOutputStream().apply{DataOutputStream(this).use{d->for(zone in names){val bytes=zone.toByteArray(Charsets.UTF_8);d.writeShort(bytes.size);d.write(bytes)}}}.toByteArray();val rows=listOf(listOf(8 to 0),listOf(4 to 0,4 to 1),listOf(4 to 0,4 to 65535),listOf(8 to 1));val runs=ByteArrayOutputStream();val indices=ArrayList<Int>();for(row in rows){indices.add(runs.size());val d=DataOutputStream(runs);for((length,zone)in row){d.writeByte(length);d.writeShort(zone)}};val indexAt=32+palette.size;val runsAt=indexAt+16;val file=File.createTempFile("timezone_raster_test_",".bin");try{DataOutputStream(file.outputStream().buffered()).use{d->d.writeBytes("BPTZ");d.writeShort(1);d.writeShort(0);d.writeInt(8);d.writeInt(4);d.writeShort(2);d.writeShort(0);d.writeInt(32);d.writeInt(indexAt);d.writeInt(runsAt);d.write(palette);indices.forEach{d.writeInt(it)};d.write(runs.toByteArray())};TimezoneRaster(file).use{r->require(r.lookup(40.0,-90.0)=="America/Denver");require(r.lookup(40.0,90.0)=="Asia/Tokyo");require(r.lookup(-20.0,90.0)==null);require(r.lookup(-90.0,180.0)=="Asia/Tokyo" );require(runCatching{r.lookup(91.0,0.0)}.isFailure)}}finally{file.delete()};println("Timezone raster lookup tests passed")}}
fun main(){RasterTests.check()}
